		public void SetRibbon(uint ribbonNo) {
            unsafe
            {
                fixed (byte* p = m_pCoreData)
                {
                    DecodeAndCheckIllegalWrite();
                    if (ribbonNo <= MAX_RIBBON_NO_ON_RIBBON_FIELD_1)
                        GetCoreDataBlockA(p, true)->ribbonA |= 1u << (int)(ribbonNo - MIN_RIBBON_NO_ON_RIBBON_FIELD_1);
                    else if (ribbonNo <= MAX_RIBBON_NO_ON_RIBBON_FIELD_2)
                        GetCoreDataBlockA(p, true)->ribbonB |= 1u << (int)(ribbonNo - MIN_RIBBON_NO_ON_RIBBON_FIELD_2);
                    else if (ribbonNo <= MAX_RIBBON_NO_ON_RIBBON_FIELD_3)
                        GetCoreDataBlockA(p, true)->ribbonC |= 1u << (int)(ribbonNo - MIN_RIBBON_NO_ON_RIBBON_FIELD_3);
                    else if (ribbonNo <= MAX_RIBBON_NO_ON_RIBBON_FIELD_4)
                        GetCoreDataBlockA(p, true)->ribbonD |= 1u << (int)(ribbonNo - MIN_RIBBON_NO_ON_RIBBON_FIELD_4);
                    UpdateChecksumAndEncode();
                }
            }
        }
