		private unsafe void copyString(char* dst, string _src, int dst_len) {
            fixed (char* src = _src)
            {
                int i = 0;
                for (; i < dst_len - 1; i++)
                {
                    if (src[i] == '\0')
                        break;
                    dst[i] = src[i];
                }
                for (; i < dst_len; i++)
                    dst[i] = '\0';
            }
        }
