		// Every GetCoreDataBlockX / GetCalcData inlines IsFuseiTamago (its own flag 0x4cc2584 tested @024a49bc / @024a4d0c / @024a50fc /
		// @024a534c / @024a723c): an illegal (fusei) egg reads the static IllegalCoreData / IllegalCalcData and writes go to the
		// DummyWrite* buffers.
		private unsafe global::Pml.PokePara.CalcData* GetCalcData(byte* _addr, bool forWrite) {
            byte* addr = _addr;
            if (IsFuseiTamago())
                addr = forWrite ? DummyWriteCalcData : IllegalCalcData;
            return (CalcData*)addr;
        }
		private unsafe global::Pml.PokePara.CoreDataBlockA* GetCoreDataBlockA(byte* _addr, bool forWrite) {
            byte* addr = _addr;
            if (IsFuseiTamago())
                addr = forWrite ? DummyWriteCoreData : IllegalCoreData;
            CoreDataHeader* header = GetCoreDataHeader(addr);
            byte pos = GetCoreDataBlockPos(header->personalRnd, CoreDataBlockId.A);
            return (CoreDataBlockA*)(addr + CoreDataHeader.SIZE + pos * CoreData.CORE_DATA_BLOCK_SIZE);
        }
		private unsafe global::Pml.PokePara.CoreDataBlockB* GetCoreDataBlockB(byte* _addr, bool forWrite) {
            byte* addr = _addr;
            if (IsFuseiTamago())
                addr = forWrite ? DummyWriteCoreData : IllegalCoreData;
            CoreDataHeader* header = GetCoreDataHeader(addr);
            byte pos = GetCoreDataBlockPos(header->personalRnd, CoreDataBlockId.B);
            return (CoreDataBlockB*)(addr + CoreDataHeader.SIZE + pos * CoreData.CORE_DATA_BLOCK_SIZE);
        }
		private unsafe global::Pml.PokePara.CoreDataBlockC* GetCoreDataBlockC(byte* _addr, bool forWrite) {
            byte* addr = _addr;
            if (IsFuseiTamago())
                addr = forWrite ? DummyWriteCoreData : IllegalCoreData;
            CoreDataHeader* header = GetCoreDataHeader(addr);
            byte pos = GetCoreDataBlockPos(header->personalRnd, CoreDataBlockId.C);
            CoreDataBlockC* block = (CoreDataBlockC*)(addr + CoreDataHeader.SIZE + pos * CoreData.CORE_DATA_BLOCK_SIZE);
            // @024a5240: the illegal-egg block always reports the current message language (PmlUse.LangId inlined @024a525c–024a52f4,
            // own flag 0x4cc2582 — b200 claim AGREED).
            if (addr == IllegalCoreData)
                block->langId = (byte)PmlUse.Instance.LangId;
            return block;
        }
		private unsafe global::Pml.PokePara.CoreDataBlockD* GetCoreDataBlockD(byte* _addr, bool forWrite) {
            byte* addr = _addr;
            if (IsFuseiTamago())
                addr = forWrite ? DummyWriteCoreData : IllegalCoreData;
            CoreDataHeader* header = GetCoreDataHeader(addr);
            byte pos = GetCoreDataBlockPos(header->personalRnd, CoreDataBlockId.D);
            return (CoreDataBlockD*)(addr + CoreDataHeader.SIZE + pos * CoreData.CORE_DATA_BLOCK_SIZE);
        }
		protected static unsafe global::Pml.PokePara.CoreDataHeader* GetCoreDataHeader(byte* addr) {
            return (CoreDataHeader*)addr;
        }
		private static byte GetCoreDataBlockPos(uint key, global::Pml.PokePara.CoreDataBlockId blockId) { unsafe {
            uint index = (key >> 13) & 0x1f;
            GFL.ASSERT(index < 32);
            GFL.ASSERT(blockId <= CoreDataBlockId.NUM);
            return BLOCK_POS_TABLE[index][(int)blockId];
        } }
		private void UpdateChecksumAndEncode() {
            if (m_accessState.isEncoded || m_accessState.isFastMode)
                return;
            updateChecksumAndEncode_Core(m_pCoreData);
            updateChecksumAndEncode_Calc(m_pCoreData, m_pCalcData);
            m_accessState.isEncoded = true;
        }
		public static void updateChecksumAndEncode_Core(byte[] pCoreData) {
            unsafe
            {
                if (pCoreData == null)
                    return;
                fixed (byte* p = pCoreData)
                {
                    CoreDataHeader* header = GetCoreDataHeader(p);
                    byte* blocks = p + CoreDataHeader.SIZE;
                    header->checksum = Encoder.CalcChecksum(blocks, CORE_DATA_SIZE - CoreDataHeader.SIZE);
                    Encoder.Encode(blocks, CORE_DATA_SIZE - CoreDataHeader.SIZE, header->personalRnd);
                }
            }
        }
		private static void updateChecksumAndEncode_Calc(byte[] pCoreData, byte[] pCalcData) {
            unsafe
            {
                if (pCoreData == null || pCalcData == null)
                    return;
                fixed (byte* core = pCoreData)
                fixed (byte* calc = pCalcData)
                {
                    CoreDataHeader* header = GetCoreDataHeader(core);
                    Encoder.Encode(calc, CALC_DATA_SIZE, header->personalRnd);
                }
            }
        }
		private void DecodeAndCheckIllegalWrite() {
            unsafe
            {
                if (!m_accessState.isEncoded)
                    return;
                fixed (byte* p = m_pCoreData)
                {
                    CoreDataHeader* header = GetCoreDataHeader(p);
                    byte* blocks = p + CoreDataHeader.SIZE;
                    Encoder.Decode(blocks, CORE_DATA_SIZE - CoreDataHeader.SIZE, header->personalRnd);
                    if (m_pCalcData != null)
                    {
                        fixed (byte* calc = m_pCalcData)
                        {
                            Encoder.Decode(calc, CALC_DATA_SIZE, header->personalRnd);
                        }
                    }
                    m_accessState.isEncoded = false;
                    // @024a43b4–024a43f8: stored checksum read before the recompute; a mismatch marks the data as an illegal egg.
                    if (header->checksum != Encoder.CalcChecksum(blocks, CORE_DATA_SIZE - CoreDataHeader.SIZE))
                        header->fuseiTamagoFlag = true;
                }
            }
        }
		private unsafe void Serialize(void* bufferForCore, void* bufferForCalc) {
            bool isFastMode = IsFastMode();
            if (isFastMode)
                EndFastMode();
            if (bufferForCore != null)
            {
                fixed (byte* p = m_pCoreData)
                {
                    UnsafeUtility.MemCpy(bufferForCore, p, CORE_DATA_SIZE);
                }
            }
            if (bufferForCalc != null)
            {
                fixed (byte* p = m_pCalcData)
                {
                    UnsafeUtility.MemCpy(bufferForCalc, p, CALC_DATA_SIZE);
                }
            }
            if (isFastMode)
                StartFastMode();
        }
		private unsafe void Deserialize(void* serializedCoreData, void* serializedCalcData) {
            if (serializedCoreData != null)
            {
                GFL.ASSERT(m_pCoreData != null);
                fixed (byte* p = m_pCoreData)
                {
                    UnsafeUtility.MemCpy(p, serializedCoreData, CORE_DATA_SIZE);
                }
            }
            if (serializedCalcData != null)
            {
                GFL.ASSERT(m_pCalcData != null);
                fixed (byte* p = m_pCalcData)
                {
                    UnsafeUtility.MemCpy(p, serializedCalcData, CALC_DATA_SIZE);
                }
            }
            m_accessState.isEncoded = true;
            m_accessState.isFastMode = false;
            DecodeAndCheckIllegalWrite();
            UpdateChecksumAndEncode();
        }
		private static void CalcWazaRecordBitPos(out byte arrayIndex, out byte bitFlag, byte recordIndex) {
            arrayIndex = (byte)(recordIndex / 8);
            bitFlag = (byte)(1 << (recordIndex % 8));
        }
		private static void CalcPokeJobBitPos(out byte arrayIndex, out byte bitFlag, byte jobIndex) {
            arrayIndex = (byte)(jobIndex / 8);
            bitFlag = (byte)(1 << (jobIndex % 8));
        }
		static Accessor() {
            // @024ac480: the four null pointers and BLOCK_POS_TABLE (32 x 4-byte blobs, all checked) are the field initialisers
        }
		private struct AccessState
		{
			public bool isEncoded;
			public bool isFastMode;
		}
	}
